import React, { useState, useEffect, useRef } from "react";

const KnowYourCandidate = ({ language }) => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const chatEndRef = useRef(null);

  const GEMINI_API_KEY = "AIzaSyDAg9-I7KPUQFnLxV0d_Cy8KM44CEm6WdE";
  const GEMINI_URL = `https://generativelanguage.googleapis.com/v1beta/models/gemini-pro:generateContent?key=${GEMINI_API_KEY}`;

  const t = {
    hindi: {
      title: "अपने उम्मीदवार को जानें 🤖",
      placeholder: "यहाँ टाइप करें जैसे — वाराणसी के लोकसभा उम्मीदवार कौन हैं?",
      send: "भेजें",
      loading: "AI सोच रहा है...",
      intro:
        "आप यहाँ अपने राज्य या क्षेत्र के उम्मीदवारों के बारे में पूछ सकते हैं। उदाहरण: 'कानपुर के 2024 लोकसभा उम्मीदवार कौन हैं?'",
    },
    english: {
      title: "Know Your Candidate 🤖",
      placeholder: "Type here, e.g. Who are the 2024 Lok Sabha candidates from Varanasi?",
      send: "Send",
      loading: "AI is thinking...",
      intro:
        "Ask about your area’s election candidates. Example: 'Who are the 2024 candidates from Lucknow?'",
    },
  }[language || "english"];

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMessage = { role: "user", text: input };
    setMessages((prev) => [...prev, userMessage]);
    setInput("");
    setLoading(true);

    try {
      const prompt = `
      You are an election assistant. A user has asked: "${input}".
      Provide factual details about 2024 Lok Sabha candidates in India relevant to their query.

      Include:
      - Candidate full name (English + Hindi)
      - Party name
      - Education
      - Political experience
      - 3-4 key promises
      - Contact or social link (if available)

      Reply in clear, structured text format, not JSON.
      Use bullet points and short paragraphs for readability.
      `;

      const response = await fetch(GEMINI_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
        }),
      });

      const data = await response.json();
      const aiText =
        data.candidates?.[0]?.content?.parts?.[0]?.text?.trim() ||
        "Sorry, I couldn’t find details for that query.";

      const aiMessage = { role: "assistant", text: aiText };
      setMessages((prev) => [...prev, aiMessage]);
    } catch (error) {
      console.error(error);
      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          text:
            language === "hindi"
              ? "माफ़ करें, अभी AI सेवा उपलब्ध नहीं है।"
              : "Sorry, the AI service is currently unavailable.",
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter" && !loading) sendMessage();
  };

  return (
    <div className="ai-chat-container">
      <div className="chat-header">
        <h2>{t.title}</h2>
        <p className="chat-intro">{t.intro}</p>
      </div>

      <div className="chat-box">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`chat-message ${
              msg.role === "user" ? "user-msg" : "ai-msg"
            }`}
          >
            <div className="message-bubble">
              {msg.role === "assistant" && <span className="ai-icon">🤖</span>}
              <p dangerouslySetInnerHTML={{ __html: msg.text.replace(/\n/g, "<br/>") }} />
            </div>
          </div>
        ))}

        {loading && (
          <div className="chat-message ai-msg">
            <div className="message-bubble loading-bubble">
              <span className="ai-icon">🤖</span>
              <span className="loading-dots">{t.loading}</span>
            </div>
          </div>
        )}

        <div ref={chatEndRef} />
      </div>

      <div className="chat-input-section">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder={t.placeholder}
          disabled={loading}
        />
        <button onClick={sendMessage} disabled={loading}>
          {t.send}
        </button>
      </div>
    </div>
  );
};

export default KnowYourCandidate;
